    train: { level: 1, xp: 0, totalXp: 0 },
    talents: emptyTalents(),
    presets: [emptyPreset("方案 A"), emptyPreset("方案 B"), emptyPreset("方案 C")],
    freeRefits: 3,
    loadout: ["hangar"],
    selectedRegion: "wasteland",
